<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Literacy in Applied Contexts — SUNY Morrisville, May 19, 2026</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/reveal.js/4.6.1/reveal.min.css">
<style>

/* ── RESET ── */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --crimson:   #8C1515;
  --crimson-d: #6B0F0F;
  --navy:      #002D62;
  --text:      #1a1a1a;
  --muted:     #4B5563;
  --border:    #D1D5DB;
  --surf:      #F9FAFB;
  --white:     #FFFFFF;
  --bg:        #f5f5f5;
  --serif:     "Computer Modern", "Latin Modern Roman", "Times New Roman", serif;
  --mono:      "JetBrains Mono", "Courier New", monospace;
  --sans:      "DM Sans", system-ui, sans-serif;
}

html, body { height: 100%; }
body {
  font-family: var(--serif);
  background: var(--bg);
  color: var(--text);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  line-height: 1.5;
}

/* ── SITE HEADER ── */
#site-header {
  background: var(--crimson);
  padding: 14px 32px 0;
  flex-shrink: 0;
}

.brand { display: flex; align-items: baseline; gap: 14px; padding-bottom: 12px; flex-wrap: wrap; }
.brand-name  { font-size: 20px; font-weight: 700; color: #fff; font-family: var(--sans); letter-spacing: 0.02em; }
.brand-sub   { font-size: 13px; color: rgba(255,255,255,0.75); font-family: var(--sans); }
.brand-date  { margin-left: auto; font-size: 11px; color: rgba(255,255,255,0.55); font-family: var(--mono); }

nav[role="tablist"] {
  display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none;
}
nav[role="tablist"]::-webkit-scrollbar { display: none; }

nav button {
  background: none; border: none; border-bottom: 3px solid transparent;
  color: rgba(255,255,255,0.7); font-family: var(--sans);
  font-size: 14px; font-weight: 500; padding: 10px 18px;
  cursor: pointer; white-space: nowrap;
  transition: all 0.15s ease; border-radius: 4px 4px 0 0;
}
nav button:hover { color: #fff; background: rgba(255,255,255,0.12); }
nav button[aria-selected="true"] { color: var(--crimson); border-bottom-color: var(--crimson); background: #fff; }
nav button:focus-visible { outline: 2px solid rgba(255,255,255,0.4); outline-offset: -2px; }

/* ── CONTENT ── */
#content { flex: 1; overflow-y: auto; }
.panel { display: none; }
.panel.active { display: block; }

/* ── TALK PANEL (reveal.js host) ── */
#panel-talk {
  height: calc(100vh - 90px);
  background: #1a1a1a;
}

.reveal-container {
  width: 100%;
  height: 100%;
}

/* ── REVEAL THEME OVERRIDE ── */
.reveal { font-family: var(--serif); }
.reveal h1, .reveal h2, .reveal h3 { color: var(--crimson); font-family: var(--serif); font-weight: normal; }
.reveal h1 { font-size: 1.8em; line-height: 1.2; }
.reveal h2 { font-size: 1.4em; line-height: 1.25; margin-bottom: 0.5em; }
.reveal h3 { font-size: 1.1em; color: var(--text); }
.reveal p  { font-size: 0.92em; line-height: 1.65; margin-bottom: 0.7em; }
.reveal ul, .reveal ol { font-size: 0.88em; line-height: 1.7; padding-left: 1.4em; }
.reveal li { margin-bottom: 0.35em; }
.reveal .mono { font-family: var(--mono); font-size: 0.82em; color: var(--muted); }
.reveal strong { color: var(--crimson); }
.reveal em { color: var(--navy); font-style: italic; }
.reveal .label {
  font-family: var(--mono); font-size: 0.65em; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--muted); margin-bottom: 0.8em; display: block;
}
.reveal .key { color: var(--crimson); font-weight: bold; }
.reveal .confession {
  background: #fff8f0; border-left: 4px solid var(--crimson);
  padding: 1em 1.2em; font-style: italic; margin: 0.8em 0;
  font-size: 0.9em; line-height: 1.6;
}
.reveal .stop-header {
  font-family: var(--mono); font-size: 0.7em; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--crimson);
  border-bottom: 1px solid #ddd; padding-bottom: 0.3em; margin-bottom: 0.8em;
}
.reveal .dashboard {
  background: #f0f4ff; border: 1px solid #c0ccee; border-radius: 6px;
  padding: 0.8em 1em; font-family: var(--mono); font-size: 0.75em;
  color: var(--navy); margin: 0.6em 0;
}
.reveal .failure-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 0.4em 1em;
  font-size: 0.82em; margin: 0.6em 0;
}
.reveal .failure-item { display: flex; gap: 0.5em; align-items: baseline; }
.reveal .failure-num { font-family: var(--mono); font-size: 0.8em; color: var(--muted); flex-shrink: 0; }
.reveal table.compare { width: 100%; font-size: 0.78em; border-collapse: collapse; margin: 0.6em 0; }
.reveal table.compare th { background: var(--crimson); color: #fff; padding: 0.5em 0.8em; text-align: left; font-family: var(--sans); font-size: 0.9em; }
.reveal table.compare td { padding: 0.5em 0.8em; border-bottom: 1px solid var(--border); vertical-align: top; }
.reveal table.compare tr:nth-child(even) td { background: #fafafa; }
.reveal .credit-question {
  font-size: 1.3em; color: var(--crimson); font-style: italic;
  text-align: center; margin-top: 0.8em; line-height: 1.4;
}
.reveal section { padding: 30px 50px !important; }

/* ── SLIDE PAGES (Text tab) ── */
.slide-page {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 36px 44px;
  margin-bottom: 20px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  border-top: 4px solid var(--crimson);
}
.slide-page--close { border-top-color: var(--navy); }
.slide-label {
  font-family: var(--mono); font-size: 0.7em; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--muted); margin-bottom: 0.8em;
}
.slide-page h2 {
  font-family: var(--serif); font-weight: normal; font-size: 1.3em;
  color: var(--crimson); margin-bottom: 0.8em; line-height: 1.25;
}
.slide-page p {
  font-size: 0.9em; line-height: 1.7; margin-bottom: 0.8em; color: var(--text);
}
.slide-page p:last-child { margin-bottom: 0; }
.slide-page strong { color: var(--crimson); }
.slide-page em { font-style: italic; color: var(--navy); }
.credit-q {
  font-size: 1.15em !important; color: var(--crimson) !important;
  font-style: italic; text-align: center; margin-top: 1em !important;
}

/* ── CONTENT PANELS (non-talk tabs) ── */
.panel-inner {
  max-width: 860px; margin: 0 auto; padding: 40px 48px;
}

.panel-inner h2 {
  color: var(--crimson); font-size: 1.4em; font-family: var(--serif);
  font-weight: normal; border-bottom: 1px solid var(--border);
  padding-bottom: 0.4em; margin-bottom: 1.2em;
}

.panel-inner h3 {
  color: var(--text); font-size: 1.05em; font-weight: bold;
  margin: 1.4em 0 0.6em;
}

.panel-inner p {
  font-size: 0.9em; line-height: 1.65; margin-bottom: 1em; color: var(--text);
}

/* Stats box */
.stats-box {
  background: linear-gradient(135deg, var(--crimson), #A91D1D);
  color: white; padding: 24px; border-radius: 8px;
  margin: 20px 0; text-align: center;
}
.stats-box h3 { color: white; margin: 0 0 12px 0; font-family: var(--sans); font-size: 1em; letter-spacing: 0.05em; text-transform: uppercase; }
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 14px; margin-top: 14px; }
.stat-item { background: rgba(255,255,255,0.18); padding: 12px; border-radius: 6px; }
.stat-number { font-size: 1.7em; font-weight: bold; font-family: var(--sans); }
.stat-label  { font-size: 0.75em; opacity: 0.85; font-family: var(--sans); margin-top: 2px; }

/* Transcript list */
.transcript-list { list-style: none; padding: 0; }
.transcript-list li {
  padding: 0.6em 0; border-bottom: 1px dotted var(--border);
  display: flex; justify-content: space-between; align-items: baseline; gap: 1em;
}
.transcript-list li:last-child { border-bottom: none; }
.transcript-list a { color: var(--crimson); text-decoration: none; font-size: 0.9em; }
.transcript-list a:hover { text-decoration: underline; }
.transcript-meta { font-size: 0.78em; color: #999; font-family: var(--mono); white-space: nowrap; }

/* Repo card */
.repo-card {
