}
.repo-card h3 { margin-top: 0; color: var(--crimson); font-size: 1em; font-weight: bold; font-family: var(--sans); }
.repo-card p { margin-bottom: 0.6em; font-size: 0.87em; line-height: 1.6; }
.repo-card code { font-family: var(--mono); font-size: 0.85em; background: var(--surf); padding: 0.15em 0.4em; border-radius: 3px; }
.prompt-box {
  background: #f8f8f6; border: 1px solid var(--border); border-radius: 6px;
  padding: 14px 18px; font-family: var(--mono); font-size: 0.82em;
  line-height: 1.6; color: var(--text); white-space: pre-wrap;
  margin: 0.8em 0;
}

</style>
