let cur = 0;
function esc(s) { const d=document.createElement('div'); d.textContent=s; return d.innerHTML; }
function pad(n) { return String(n).padStart(2,'0'); }

function renderProgress() {
  const el = document.getElementById('progress');
  el.innerHTML = slides.map((_,i) => {
    const cls = i===cur?'active':i<cur?'visited':'';
    return '<div class="progress-pip '+cls+'" onclick="slideGoTo('+i+')"></div>';
  }).join('');
}

function renderSlide() {
  const s = slides[cur];
  document.getElementById('counter').textContent = pad(cur+1)+' / '+pad(slides.length);
  document.getElementById('timing').textContent = '⏱ '+s.note;
  const c = document.getElementById('slideContent');
  c.style.animation = 'none'; c.offsetHeight; c.style.animation = 'fadeSlide 0.4s ease both';
  let h = '';

  if (s.type==='title') {
    h = '<div style="display:flex;flex-direction:column;justify-content:center;height:280px"><div class="mono sl-title-meta">'+esc(s.meta)+'</div><h1 class="sl-title-main">'+esc(s.title)+'</h1><p class="sl-title-sub">'+esc(s.subtitle)+'</p></div>';
  } else if (s.type==='closing') {
    h = '<div style="display:flex;flex-direction:column;justify-content:center;height:280px"><h1 class="sl-closing-main">'+esc(s.title)+'</h1><div class="sl-closing-border"><p class="sl-closing-text">'+esc(s.subtitle)+'</p></div></div>';
  } else if (s.type==='bullets') {
    h = '<h1 class="sl-title">'+esc(s.title)+'</h1><div class="sl-bullet-list">';
    s.body.forEach((item,i) => { h += '<div class="sl-bullet-item stagger" style="animation-delay:'+i*70+'ms"><div class="sl-bullet-marker"></div><span class="sl-bullet-text">'+esc(item)+'</span></div>'; });
    h += '</div>';
  } else if (s.type==='architecture') {
    h = '<h1 class="sl-title">'+esc(s.title)+'</h1><div class="sl-layer-stack">';
    s.layers.forEach((l,i) => { h += '<div class="sl-layer-row stagger" style="border-left-color:'+l.accent+';background:'+l.bg+';animation-delay:'+i*70+'ms"><span class="mono sl-layer-label" style="color:'+l.accent+'">'+esc(l.label)+'</span><p class="sl-layer-desc">'+esc(l.desc)+'</p></div>'; });
    h += '</div>';
  } else if (s.type==='table') {
    h = '<h1 class="sl-title">'+esc(s.title)+'</h1><div class="sl-table-wrap"><table><thead><tr>';
    s.headers.forEach(hd => { h += '<th>'+esc(hd)+'</th>'; });
    h += '</tr></thead><tbody>';
    s.rows.forEach((row,i) => {
      const tc = row[0]==='Framing'?'sl-tier-framing':'sl-tier-operational';
      h += '<tr class="stagger" style="animation-delay:'+i*70+'ms"><td><span class="sl-tier-badge '+tc+'">'+esc(row[0])+'</span></td><td style="color:#1a1a2e;font-weight:500">'+esc(row[1])+'</td><td style="color:rgba(0,0,0,0.45)">'+esc(row[2])+'</td></tr>';
    });
    h += '</tbody></table></div>';
  } else if (s.type==='split') {
    h = '<h1 class="sl-title">'+esc(s.title)+'</h1><div class="sl-split-grid">';
    [s.left,s.right].forEach((col,ci) => {
      h += '<div class="sl-split-col stagger" style="animation-delay:'+ci*70+'ms"><div class="mono sl-split-label" style="color:'+col.accent+'">'+esc(col.label)+'</div><div class="sl-split-points">';
      col.points.forEach(p => { h += '<div class="sl-split-point"><div class="sl-split-dot" style="background:'+col.accent+'"></div><span class="sl-split-text">'+esc(p)+'</span></div>'; });
      h += '</div></div>';
    });
    h += '</div>';
  } else if (s.type==='capstone') {
    h = '<h1 class="sl-title">'+esc(s.title)+'</h1><div class="sl-cap-grid">';
    s.projects.forEach((p,i) => { h += '<div class="sl-cap-card stagger" style="animation-delay:'+i*70+'ms"><div class="sl-cap-title">'+esc(p.title)+'</div><p class="sl-cap-desc">'+esc(p.desc)+'</p></div>'; });
    h += '</div>';
  }
  c.innerHTML = h;
  document.getElementById('prevBtn').disabled = cur===0;
  document.getElementById('nextBtn').disabled = cur===slides.length-1;
  renderProgress();
}

function slideGo(dir) { const n=cur+dir; if(n>=0&&n<slides.length){cur=n;renderSlide();} }
function slideGoTo(i) { cur=i; renderSlide(); }

document.getElementById('slidesWrap').addEventListener('keydown', (e) => {
  if (e.key==='ArrowRight'||e.key===' ') { e.preventDefault(); slideGo(1); }
  if (e.key==='ArrowLeft') { e.preventDefault(); slideGo(-1); }
});

renderSlide();
</script>
